def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    y = []
    last = 0.0
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                last = z
        except Exception:
            pass
        y.append(last)
    if not y:
        return [0.0] * horizon
    if len(y) < 4:
        return [y[-1]] * horizon

    def median(a):
        b = sorted(a)
        q = len(b)
        return b[q // 2] if q % 2 else 0.5 * (b[q // 2 - 1] + b[q // 2])

    d = [abs(y[i] - y[i - 1]) for i in range(1, len(y))]
    scale = median(d) + 1e-12
    j = max(range(len(d)), key=lambda i: d[i]) + 1
    start = max(0, len(y) - 96)
    if d[j - 1] > 8.0 * scale:
        low = min(range(j, len(y)), key=lambda i: y[i])
        if len(y) - low >= 20:
            start = low
    a = y[start:]
    m = len(a)
    if m < 3:
        return [a[-1]] * horizon

    xs = [i - (m - 1) for i in range(m)]
    s1 = sum(xs); s2 = sum(x*x for x in xs); s3 = sum(x*x*x for x in xs); s4 = sum(x*x*x*x for x in xs)
    t0 = sum(a); t1 = sum(x*v for x, v in zip(xs, a)); t2 = sum(x*x*v for x, v in zip(xs, a))
    mat = [[float(m), s1, s2, t0], [s1, s2, s3, t1], [s2, s3, s4, t2]]
    for col in range(3):
        pivot = max(range(col, 3), key=lambda r: abs(mat[r][col]))
        mat[col], mat[pivot] = mat[pivot], mat[col]
        if abs(mat[col][col]) < 1e-12:
            return [a[-1]] * horizon
        q = mat[col][col]
        mat[col] = [v / q for v in mat[col]]
        for r in range(3):
            if r != col:
                q = mat[r][col]
                mat[r] = [mat[r][k] - q * mat[col][k] for k in range(4)]
    level, slope, curve = [mat[i][3] for i in range(3)]
    limit = 3.0 * (abs(slope) + scale) / max(10.0, float(m))
    curve = max(-limit, min(limit, curve))
    out = []
    for k in range(1, horizon + 1):
        v = level + slope * k + curve * k * k
        out.append(v if math.isfinite(v) else out[-1] if out else y[-1])
    return out

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    y = []
    for v in history:
        try:
            z = float(v)
            y.append(z if math.isfinite(z) else (y[-1] if y else 0.0))
        except Exception:
            y.append(y[-1] if y else 0.0)
    if not y:
        return [0.0] * horizon

    def solve(vals, degree, steps):
        m = len(vals)
        if m < degree + 1:
            return [vals[-1]] * steps
        xs = [(i - (m - 1)) / max(1.0, float(m - 1)) for i in range(m)]
        p = degree + 1
        mat = []
        for r in range(p):
            mat.append([sum(x ** (r + c) for x in xs) for c in range(p)] + [sum(v * (x ** r) for x, v in zip(xs, vals))])
        for c in range(p):
            pivot = max(range(c, p), key=lambda r: abs(mat[r][c]))
            mat[c], mat[pivot] = mat[pivot], mat[c]
            if abs(mat[c][c]) < 1e-12:
                return [vals[-1]] * steps
            q = mat[c][c]
            mat[c] = [v / q for v in mat[c]]
            for r in range(p):
                if r != c:
                    q = mat[r][c]
                    mat[r] = [mat[r][j] - q * mat[c][j] for j in range(p + 1)]
        coef = [mat[i][p] for i in range(p)]
        out = []
        for k in range(1, steps + 1):
            x = k / max(1.0, float(m - 1))
            v = sum(coef[j] * x ** j for j in range(p))
            out.append(v if math.isfinite(v) else vals[-1])
        return out

    n = len(y)
    jumps = [abs(y[i] - y[i - 1]) for i in range(1, n)]
    ordered = sorted(jumps)
    med = ordered[len(ordered) // 2] if ordered else 0.0
    regime = 0
    if jumps:
        j = max(range(len(jumps)), key=lambda i: jumps[i]) + 1
        if jumps[j - 1] > 8.0 * (med + 1e-12):
            low = min(range(j, n), key=lambda i: y[i])
            if n - low >= 24:
                regime = low
    r = y[regime:]
    nr = len(r)
    block = min(max(12, nr // 4), 36)
    scored = []
    for degree in (1, 2):
        for w in (24, 32, 48, 64):
            errors = []
            for back in (block, 2 * block):
                cut = nr - back
                if cut < w:
                    continue
                pred = solve(r[cut - w:cut], block, degree)
                for k in range(block):
                    actual = r[cut + k]
                    f = pred[k]
                    errors.append(2.0 * abs(f - actual) / (abs(f) + abs(actual) + 1e-9))
            if errors:
                scored.append((sum(errors) / len(errors), degree, w))
    if not scored:
        return [y[-1]] * horizon
    scored.sort()
    chosen = scored[:min(3, len(scored))]
    base = chosen[0][0]
    weights = [1.0 / (s[0] + 0.01) if s[0] <= base + 0.02 else 0.0 for s in chosen]
    paths = [solve(r[-min(s[2], nr):], s[1], horizon) for s in chosen]
    total = sum(weights)
    if total <= 0.0:
        return paths[0]
    return [sum(weights[i] * paths[i][k] for i in range(len(paths))) / total for k in range(horizon)]
